#!/bin/bash
# Code generated by schemaf codegen. DO NOT EDIT.
# Regenerate with: ./schemaf.sh codegen
#
# schemaf.sh — the project entrypoint, in two modes:
#
#   checkout  next to schemaf.toml: codegen, test, dev, build, run, upgrade and
#             the app's own subcommands (via `go run`).
#   run side  installed as ~/.chatgamelab/bin/schemaf.sh by a deployment artifact's
#             `load`, with no checkout: run --image, stop, status, logs, image,
#             and app subcommands exec'd in the running backend container.
#
# ARCHITECTURE: everything that can run in Go does (cli/cmd/*/). The shell holds
# only what must work without Go: finding the project root, loading env vars,
# and build / run / load / the run side, because build and run hosts have no
# Go (see INSTALL.md › Deployment). Do not add application logic here.
#
# Bash 3.2 compatible (macOS /bin/bash): no mapfile, no associative arrays,
# no empty-array expansion under `set -u`.
set -euo pipefail

# Fail loudly. Under `set -e`, an unexpected error (e.g. a pipeline member killed
# by SIGPIPE → exit 141) otherwise aborts the script silently with only a numeric
# exit code. This trap reports the failing command, line, and exit code instead.
trap 'rc=$?; echo "ERROR: schemaf.sh failed at line ${LINENO}: \"${BASH_COMMAND}\" (exit ${rc})" >&2; exit ${rc}' ERR

PROJECT_NAME="chatgamelab"
PROJECT_PORT="7100"
# load reads the installed run-side script's version from this exact line
# (_schemaf_script_version), so it never replaces a newer script with an older one.
SCHEMAF_VER="v1.23.0"
ORIG_PWD="$PWD"
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
USER_DIR="$HOME/.${PROJECT_NAME}"
DEPLOY_DIR="$USER_DIR/deploy"
NO_CHECKOUT="this host has no checkout; that command runs on a dev or build host"

# A parallel dev instance's compose names and Postgres port (cli.InstanceComposeEnv).
# Only `dev` sets them, in Go; everything schemaf.sh starts is the default stack,
# so they are dropped here and never loaded from an env file.
unset SCHEMAF_INSTANCE_SUFFIX SCHEMAF_POSTGRES_PORT

# Go template delimiters for --format arguments of the container CLI.
_O='{{' _C='}}'

# Temporary directories, removed on exit.
_SCHEMAF_TMP=""
# Temporary directories carry this process's PID in their name, so clean-up
# finds the ones made in subshells too ($(_schemaf_mktemp) can't register
# them; $$ is the script's PID in every subshell).
_schemaf_cleanup() {
  local d
  for d in $_SCHEMAF_TMP "${TMPDIR:-/tmp}"/schemaf.$$.*; do
    [ -e "$d" ] || continue
    rm -rf "${d:?}"
  done
  _SCHEMAF_TMP=""
}
trap _schemaf_cleanup EXIT
_schemaf_mktemp() {
  local d
  d=$(mktemp -d "${TMPDIR:-/tmp}/schemaf.$$.XXXXXX")
  _SCHEMAF_TMP="$_SCHEMAF_TMP $d"
  echo "$d"
}

_die() {
  echo "ERROR: $*" >&2
  exit 1
}

# Load env vars from a file. Only sets variables not already in the environment.
# Development mode belongs to schemaf.sh (EXTEND.md › Development mode): an env
# file that sets SCHEMAF_DEV, to any value, stops schemaf.sh before it starts
# anything, rather than being silently overridden.
_schemaf_refuse_dev_mode_in() {
  local envfile="$1" key val
  [ -f "$envfile" ] || return 0
  while IFS='=' read -r key val; do
    key=$(echo "$key" | xargs)
    [ "$key" != SCHEMAF_DEV ] || _die "$envfile sets SCHEMAF_DEV, but development mode is not configured in env files: schemaf.sh sets SCHEMAF_DEV=1 for every command except build and run (EXTEND.md › Development mode). Remove the SCHEMAF_DEV line from $envfile."
  done < "$envfile"
}

_schemaf_load_env() {
  local envfile="$1" key val
  [ -f "$envfile" ] || return 0
  _schemaf_refuse_dev_mode_in "$envfile"
  while IFS='=' read -r key val; do
    key=$(echo "$key" | xargs)
    [ -z "$key" ] || [[ "$key" == \#* ]] && continue
    case "$key" in SCHEMAF_INSTANCE_SUFFIX|SCHEMAF_POSTGRES_PORT) continue ;; esac
    val=$(echo "$val" | xargs)
    if [ -z "${!key:-}" ]; then
      export "$key=$val"
    fi
  done < "$envfile"
}

# Read only SCHEMAF_RUNTIME from an env file, if the environment doesn't set it.
# build uses this instead of _schemaf_load_env: it runs third-party code
# (npm install) and must never see the other variables (INSTALL.md › Secrets).
_schemaf_env_runtime() {
  local envfile="$1" key val
  _schemaf_refuse_dev_mode_in "$envfile"
  [ -z "${SCHEMAF_RUNTIME:-}" ] || return 0
  [ -f "$envfile" ] || return 0
  while IFS='=' read -r key val; do
    key=$(echo "$key" | xargs)
    if [ "$key" = SCHEMAF_RUNTIME ]; then
      export SCHEMAF_RUNTIME="$(echo "$val" | xargs)"
      return 0
    fi
  done < "$envfile"
}

# Every container call goes through _schemaf_container — never call podman or
# docker directly. The runtime is SCHEMAF_RUNTIME: podman (the default) or docker.
# See INSTALL.md › Container runtime.
#   --exec   the runtime replaces this shell
#   --other  run the runtime that is NOT selected (for the data volume check)
_schemaf_container() {
  local rt="${SCHEMAF_RUNTIME:-podman}" use_exec=0 other=0
  while :; do
    case "${1:-}" in
      --exec) use_exec=1; shift ;;
      --other) other=1; shift ;;
      *) break ;;
    esac
  done
  case "$rt" in
    podman|docker) ;;
    *)
      echo "ERROR: SCHEMAF_RUNTIME=\"$rt\" is not a valid container runtime — valid values: podman (the default), docker" >&2
      return 1
      ;;
  esac
  if [ "$other" = 1 ]; then
    if [ "$rt" = podman ]; then rt=docker; else rt=podman; fi
    command -v "$rt" >/dev/null 2>&1 || { echo "ERROR: $rt is not installed" >&2; return 1; }
  elif ! command -v "$rt" >/dev/null 2>&1; then
    if [ "$rt" = podman ]; then
      echo "ERROR: podman is not installed — install podman and docker-compose, or set SCHEMAF_RUNTIME=docker" >&2
    else
      echo "ERROR: SCHEMAF_RUNTIME=docker, but docker is not installed — install Docker, or unset SCHEMAF_RUNTIME to use podman" >&2
    fi
    return 1
  fi
  # podman compose announces its external provider on every call; silence it.
  export PODMAN_COMPOSE_WARNING_LOGS="${PODMAN_COMPOSE_WARNING_LOGS:-false}"
  if [ "$use_exec" = 1 ]; then
    _schemaf_cleanup   # exec skips the EXIT trap
    exec "$rt" "$@"
  fi
  "$rt" "$@"
}

# _schemaf_check_runtime [compose] — the selected runtime is installed and its
# engine answers; with "compose", its compose is docker-compose (Compose v2).
# Mirrors the Go checks (cli.CheckRuntime) for the commands that run without Go.
_schemaf_check_runtime() {
  local rt="${SCHEMAF_RUNTIME:-podman}" out
  _schemaf_container --help >/dev/null || exit 1
  if ! out=$(_schemaf_container info 2>&1); then
    echo "ERROR: $rt is installed, but not usable. $rt info said:" >&2
    echo "$out" | sed 's/^/  /' >&2
    if [ "$rt" = podman ] && [ "$(uname)" = Darwin ]; then
      echo "Start the podman machine: podman machine start (create it once first: podman machine init)" >&2
    elif [ "$rt" = docker ]; then
      echo "Start Docker (Docker Desktop, or: sudo systemctl start docker), or unset SCHEMAF_RUNTIME to use podman" >&2
    fi
    echo "See INSTALL.md › Container runtime (docs/schemaf/INSTALL.md)" >&2
    exit 1
  fi
  [ "${1:-}" = compose ] || return 0
  out=$(_schemaf_container compose version 2>&1) || true
  case "$out" in
    *"Docker Compose version"*) ;;
    *)
      echo "ERROR: $rt compose must be docker-compose (Compose v2). $rt compose version said:" >&2
      echo "$out" | sed 's/^/  /' >&2
      echo "Install docker-compose (macOS: brew install docker-compose; other systems: https://github.com/docker/compose/releases)" >&2
      echo "See INSTALL.md › Container runtime (docs/schemaf/INSTALL.md)" >&2
      exit 1
      ;;
  esac
  _schemaf_check_podman_socket
}

# _schemaf_check_podman_socket — podman compose hands off to docker-compose,
# which talks to podman through its API socket: DOCKER_HOST if set, else
# podman's own (on Linux the user's podman.socket). Fails when it doesn't
# answer, pinged with podman's remote client. On macOS the podman machine
# provides it. Never starts anything. Mirrors Go's checkPodmanSocket; the
# message is rendered from Go's (cli.PodmanSocketText).
_schemaf_check_podman_socket() {
  local sock fix out said
  [ "${SCHEMAF_RUNTIME:-podman}" = podman ] || return 0
  [ "$(uname)" != Darwin ] || return 0
  # podman compose passes an existing DOCKER_HOST on as is, even an empty one.
  if [ -n "${DOCKER_HOST+set}" ] && [ -z "$DOCKER_HOST" ]; then
    echo "ERROR: DOCKER_HOST is set but empty: podman compose passes it on as is, so docker-compose would not reach podman. Unset it, or point it at podman's socket." >&2
    exit 1
  fi
  if [ -n "${DOCKER_HOST:-}" ]; then
    sock="$DOCKER_HOST" fix="The address comes from DOCKER_HOST: point DOCKER_HOST at podman's socket, or unset it to use podman's own (start that once: systemctl --user enable --now podman.socket)."
  else
    fix="Start it once (it stays enabled):
  systemctl --user enable --now podman.socket"
    sock=$(_schemaf_container info --format '{{.Host.RemoteSocket.Path}}' 2>/dev/null) || sock=""
    if [ -z "$sock" ]; then
      echo "ERROR: podman compose hands off to docker-compose, which needs podman's API socket, but podman info doesn't report its path (podman info --format '{{.Host.RemoteSocket.Path}}')" >&2
      exit 1
    fi
    case "$sock" in *://*) ;; *) sock="unix://$sock" ;; esac
  fi
  # stderr only: on failure, version still prints the client part to stdout.
  out=$(_schemaf_container --remote --url "$sock" version 2>&1 >/dev/null) && return 0
  said=$(printf '%s\n' "$out" | sed 's/^/  /')
  [ -n "$out" ] || said="  (no output)"
  cat >&2 <<EOF
ERROR: podman's API socket isn't running: nothing answers at ${sock}.
podman compose hands off to docker-compose, which talks to podman through that socket.
${fix}
podman said:
${said}
EOF
  exit 1
}

# Refuse to start when the other runtime holds the project's Postgres volume
# (INSTALL.md › Container runtime). Skipped when the other runtime isn't
# installed or usable. Never migrates or deletes anything. The message is
# rendered from Go's (cli.VolumeConflictMessage), so both print the same text.
_schemaf_check_volume() {
  local vol="${PROJECT_NAME}-postgres-data" rt="${SCHEMAF_RUNTIME:-podman}" other hint both=""
  _schemaf_container --other info >/dev/null 2>&1 || return 0
  _schemaf_container --other volume inspect "$vol" >/dev/null 2>&1 || return 0
  if [ "$rt" = podman ]; then
    other=docker hint="set SCHEMAF_RUNTIME=docker"
  else
    other=podman hint="unset SCHEMAF_RUNTIME (podman is the default)"
  fi
  if _schemaf_container volume inspect "$vol" >/dev/null 2>&1; then
    both=$'\n'"${rt} has its own chatgamelab-postgres-data as well, so it is unclear which holds the real data."
  fi
  cat >&2 <<EOF
ERROR: refusing to start: the Postgres volume chatgamelab-postgres-data exists in ${other}, but the selected container runtime is ${rt}.${both}
The project's data volume may exist only in the selected runtime. Choose one:

  1. Migrate the data to ${rt} (a move, not a copy). From the project root (on a run host: ~/.chatgamelab/deploy/<running tag>/):
       set -a; . ~/.chatgamelab/etc/env; set +a          # dev: ~/.chatgamelab/dev/etc/env
       export SCHEMAF_IMAGE=chatgamelab:unused             # required by compose.gen.yml; only postgres starts
       ${other} compose -f compose.gen.yml down
       ${other} compose -f compose.gen.yml up -d --wait postgres
       ${other} exec chatgamelab-postgres pg_dump -U schemaf -d chatgamelab > chatgamelab.sql
       ${other} compose -f compose.gen.yml down
       ${rt} compose -f compose.gen.yml up -d --wait postgres
       ${rt} exec -i chatgamelab-postgres psql -U schemaf -d chatgamelab -v ON_ERROR_STOP=1 < chatgamelab.sql
       # verify the data (tables, row counts), then:
       ${rt} compose -f compose.gen.yml down
       ${other} volume rm chatgamelab-postgres-data
     Step by step: INSTALL.md › Migrating from Docker to podman (docs/schemaf/INSTALL.md)

  2. Or keep the data where it is and use ${other}: ${hint}
     (in your shell profile, or in ~/.chatgamelab/etc/env and ~/.chatgamelab/dev/etc/env).

  3. Or, if the data is throwaway, delete it:
       ${other} volume rm chatgamelab-postgres-data
EOF
  exit 1
}

# >>> inputs-hash — the shell side of gen/inputs.sha256 (cli/cmd/codegen/inputs.go).
# The input list is rendered from Go's inputGlobs and schemaSourceExcludes; a
# test checks both agree. _schemaf_inputs_hash hashes the working tree,
# _schemaf_commit_inputs_hash the same inputs as committed (build --output).

# stdin → hex SHA-256.
_schemaf_sha256() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum | cut -d' ' -f1
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 | cut -d' ' -f1
  else
    echo "ERROR: neither sha256sum nor shasum is installed — install coreutils (sha256sum) or perl (shasum)" >&2
    return 1
  fi
}

# The schemaf version required in go.mod (on stdin): the first non-comment line
# holding the module path directly followed by a field starting with "v".
_schemaf_gomod_version() {
  local v
  v=$(awk '$1 !~ /^\/\// { for (i = 1; i < NF; i++) if ($i == "github.com/flocko-motion/schemaf" && $(i+1) ~ /^v/) { print $(i+1); exit } }')
  [ -n "$v" ] || { echo "ERROR: go/go.mod requires no version of github.com/flocko-motion/schemaf" >&2; return 1; }
  echo "$v"
}

_schemaf_inputs_hash() (
  shopt -s nullglob
  list=""
  for f in go/api/*.go go/db/migrations/* go/db/queries/* schemaf.toml compose/*.yml; do
    [ -f "$f" ] || continue
    case "$f" in go/api/*.gen.go|go/api/*_test.go) continue ;; esac
    list="${list}${f}"$'\n'
  done
  # The packages declaring the API's types, one glob per line (gen/schema-sources).
  if [ -f gen/schema-sources ]; then
    while IFS= read -r g || [ -n "$g" ]; do
      [ -n "$g" ] || continue
      for f in $g; do
        [ -f "$f" ] || continue
        case "${f##*/}" in .*|*.gen.go|*_test.go) continue ;; esac
        list="${list}${f}"$'\n'
      done
    done < gen/schema-sources
  fi
  [ -f go/go.mod ] || { echo "ERROR: go/go.mod not found" >&2; exit 1; }
  ver=$(_schemaf_gomod_version < go/go.mod) || exit 1
  {
    printf '%s' "$list" | LC_ALL=C sort -u | while IFS= read -r f; do
      [ -n "$f" ] || continue
      sum=$(_schemaf_sha256 < "$f") || exit 1
      printf '%s  %s\n' "$sum" "$f"
    done
    printf 'schemaf %s\n' "$ver"
  } | _schemaf_sha256
)

# _schemaf_commit_glob <commit> <glob> — the files of the commit that match
# the glob (relative to the current directory), one per line as "F <path>" for
# a regular file or "L <path>" for a symlink, by the rules of the working-tree
# expansion: a wildcard matches neither "/" nor a leading ".". Submodules and
# directories are not files.
_schemaf_commit_glob() {
  local commit="$1" prefix="" entry meta path kind ok i c p
  local -a pat comp
  IFS=/ read -r -a pat <<< "$2"
  # Only the literal leading directories narrow the listing.
  for ((i = 0; i < ${#pat[@]} - 1; i++)); do
    case "${pat[i]}" in *[*?[]*) break ;; esac
    prefix="${prefix}${pat[i]}/"
  done
  git ls-tree -r -z "$commit" -- ${prefix:+"$prefix"} | while IFS= read -r -d '' entry; do
    meta="${entry%%$'\t'*}" path="${entry#*$'\t'}"
    case "${meta%% *}" in 100644|100755) kind=F ;; 120000) kind=L ;; *) continue ;; esac
    IFS=/ read -r -a comp <<< "$path"
    [ "${#comp[@]}" -eq "${#pat[@]}" ] || continue
    ok=1
    for ((i = 0; i < ${#pat[@]}; i++)); do
      c="${comp[i]}" p="${pat[i]}"
      if [[ $c == .* && $p != .* ]] || [[ $c != $p ]]; then ok=0; break; fi
    done
    if [ "$ok" = 1 ]; then printf '%s %s\n' "$kind" "$path"; fi
  done
}

# _schemaf_commit_inputs_hash <commit> — the inputs hash over the commit's
# versions of the input files, gen/schema-sources and go/go.mod. Untracked and
# ignored files are not part of it: the commit is what an artifact ships. An
# input committed as a symlink is an error: the working tree follows it, the
# commit holds only the link.
_schemaf_commit_inputs_hash() (
  set -f
  commit="$1"
  list=""
  symlink() {
    echo "ERROR: input $1 is a symlink in commit ${commit:0:7} — an artifact ships the commit, commit the file itself" >&2
    exit 1
  }
  for g in go/api/*.go go/db/migrations/* go/db/queries/* schemaf.toml compose/*.yml; do
    files=$(_schemaf_commit_glob "$commit" "$g") || exit 1
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      f="${line#? }"
      case "$f" in go/api/*.gen.go|go/api/*_test.go) continue ;; esac
      [ "${line%% *}" = F ] || symlink "$f"
      list="${list}${f}"$'\n'
    done <<< "$files"
  done
  # The packages declaring the API's types, as listed in the commit.
  if git cat-file -e "$commit:./gen/schema-sources" 2>/dev/null; then
    sources=$(git cat-file blob "$commit:./gen/schema-sources") || exit 1
    while IFS= read -r g; do
      [ -n "$g" ] || continue
      files=$(_schemaf_commit_glob "$commit" "$g") || exit 1
      while IFS= read -r line; do
        [ -n "$line" ] || continue
        f="${line#? }"
        case "${f##*/}" in .*|*.gen.go|*_test.go) continue ;; esac
        [ "${line%% *}" = F ] || symlink "$f"
        list="${list}${f}"$'\n'
      done <<< "$files"
    done <<< "$sources"
  fi
  git cat-file -e "$commit:./go/go.mod" 2>/dev/null \
    || { echo "ERROR: go/go.mod is not in commit ${commit:0:7}" >&2; exit 1; }
  ver=$(git cat-file blob "$commit:./go/go.mod" | _schemaf_gomod_version) || exit 1
  {
    printf '%s' "$list" | LC_ALL=C sort -u | while IFS= read -r f; do
      [ -n "$f" ] || continue
      sum=$(git cat-file blob "$commit:./$f" | _schemaf_sha256) || exit 1
      printf '%s  %s\n' "$sum" "$f"
    done
    printf 'schemaf %s\n' "$ver"
  } | _schemaf_sha256
)
# <<< inputs-hash

# Refuse when generated files don't match their inputs (EXTEND.md › Code Generation).
# _schemaf_check_fresh checks the working tree (plain build, run, test);
# _schemaf_check_fresh_commit <commit> checks the commit (build --output), so a
# generated file that depends on an untracked or ignored input is stale there.
_schemaf_check_fresh() {
  local want got
  [ -f gen/inputs.sha256 ] || _die "gen/inputs.sha256 not found — run ./schemaf.sh codegen and commit"
  want=$(tr -d '[:space:]' < gen/inputs.sha256)
  got=$(_schemaf_inputs_hash) || exit 1
  [ "$want" = "$got" ] || _die "generated files are stale — run ./schemaf.sh codegen and commit"
}

_schemaf_check_fresh_commit() {
  local commit="$1" want got
  git cat-file -e "$commit:./gen/inputs.sha256" 2>/dev/null \
    || _die "gen/inputs.sha256 is not in commit ${commit:0:7} — run ./schemaf.sh codegen and commit"
  want=$(git cat-file blob "$commit:./gen/inputs.sha256" | tr -d '[:space:]')
  got=$(_schemaf_commit_inputs_hash "$commit") || exit 1
  [ "$want" = "$got" ] || _die "generated files are stale — run ./schemaf.sh codegen and commit"
}

# Print codegen's warnings about empty inputs (EXTEND.md › Empty inputs).
# Empty input is valid: this never fails.
_schemaf_warn_empty_inputs() {
  local line
  [ -f gen/empty-inputs ] || return 0
  while IFS= read -r line || [ -n "$line" ]; do
    if [ -n "$line" ]; then echo "⚠ $line" >&2; fi
  done < gen/empty-inputs
}

# --- images -------------------------------------------------------------------

_schemaf_image_exists() {
  _schemaf_container image inspect "$1" >/dev/null 2>&1
}

# _schemaf_image_label <image> <label> — the label's value, empty if unset.
_schemaf_image_label() {
  _schemaf_container image inspect --format "${_O}index .Config.Labels \"$2\"${_C}" "$1"
}

_schemaf_check_tag() {
  local re='^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$'
  [[ "$1" =~ $re ]] || _die "invalid tag \"$1\" — use letters, digits, _ . - (at most 128, not starting with . or -)"
}

# The platform this host runs images for, as the image's Os/Architecture.
_schemaf_host_platform() {
  case "$(uname -m)" in
    x86_64|amd64) echo linux/amd64 ;;
    aarch64|arm64) echo linux/arm64 ;;
    *) echo "linux/$(uname -m)" ;;
  esac
}

# The backend container's state and image tag: "<running> <tag>", e.g.
# "true 3f9a2c1"; empty when there is no backend container.
_schemaf_backend() {
  local out
  out=$(_schemaf_container container inspect --format "${_O}.State.Running${_C} ${_O}.Config.Image${_C}" "${PROJECT_NAME}-backend" 2>/dev/null) || return 0
  echo "${out%% *} ${out##*:}"
}

# The tag of the running backend, empty if none is running.
_schemaf_running_tag() {
  local b
  b=$(_schemaf_backend)
  [ "${b%% *}" = true ] && echo "${b#* }" || true
}

_schemaf_manifest_get() {
  local v
  v=$(grep "^$2=" "$1" | head -n 1) || true
  echo "${v#*=}"
}

# --- build (checkout) ---------------------------------------------------------

# _schemaf_build [--tag <tag>] [--output <file>] [--force]
# Sets BUILT_IMAGE. See INSTALL.md › Deployment › build.
_schemaf_build() {
  local tag="" output="" force=0 commit short describe dirty=false ctx have
  while [ $# -gt 0 ]; do
    case "$1" in
      --tag) [ $# -ge 2 ] || _die "--tag needs a value"; tag="$2"; shift 2 ;;
      --tag=*) tag="${1#--tag=}"; shift ;;
      --output) [ $# -ge 2 ] || _die "--output needs a file"; output="$2"; shift 2 ;;
      --output=*) output="${1#--output=}"; shift ;;
      --force) force=1; shift ;;
      *) _die "build: unknown argument \"$1\" — usage: ./schemaf.sh build [--tag <tag>] [--output <file>] [--force]" ;;
    esac
  done

  command -v git >/dev/null 2>&1 || _die "build needs git — the image is named after its commit"
  git rev-parse --git-dir >/dev/null 2>&1 || _die "build needs a git repository — the image is named after its commit"
  commit=$(git rev-parse --verify -q HEAD) || _die "build needs a commit — this repository has none yet"
  short=$(git rev-parse --short HEAD)
  [ -z "$(git status --porcelain)" ] || dirty=true
  describe=$(git describe --tags --always --dirty)

  if [ -n "$output" ]; then
    [ "$dirty" = false ] || _die "commit first — a deployment artifact must name exactly one commit"
    case "$output" in /*) ;; *) output="$ORIG_PWD/$output" ;; esac
    [ ! -e "$output" ] && [ ! -L "$output" ] || _die "$output already exists — remove it or choose another --output"
    [ -d "$(dirname "$output")" ] || _die "$(dirname "$output") does not exist"
  fi
  if [ -z "$tag" ]; then
    tag="$short"
    [ "$dirty" = false ] || tag="${short}-dirty"
  fi
  _schemaf_check_tag "$tag"
  # An artifact ships the commit, so its inputs are checked as committed.
  if [ -n "$output" ]; then _schemaf_check_fresh_commit "$commit"; else _schemaf_check_fresh; fi
  _schemaf_warn_empty_inputs
  _schemaf_check_runtime

  BUILT_IMAGE="${PROJECT_NAME}:${tag}"
  if _schemaf_image_exists "$BUILT_IMAGE"; then
    have=$(_schemaf_image_label "$BUILT_IMAGE" schemaf.commit)
    if [ "$dirty" = false ] && [ "$force" = 0 ] && [ "$have" = "$commit" ] \
      && [ "$(_schemaf_image_label "$BUILT_IMAGE" schemaf.dirty)" = false ]; then
      echo "Already built: $BUILT_IMAGE (commit $short) — --force rebuilds it" >&2
      [ -z "$output" ] || _schemaf_write_artifact "$output" "$tag" "$commit" "$describe"
      return 0
    fi
    if [ -n "$have" ] && [ "$have" != "$commit" ]; then
      echo "Replacing $BUILT_IMAGE (was commit ${have:0:7}) with commit $short" >&2
    fi
  fi

  if [ "$dirty" = true ]; then
    echo "Building $BUILT_IMAGE from the working tree (uncommitted changes)..." >&2
    ctx="$PROJECT_ROOT"
  else
    # Exactly the commit: untracked and ignored files never reach the image.
    echo "Building $BUILT_IMAGE from commit $short..." >&2
    ctx=$(_schemaf_mktemp)
    git archive HEAD | tar -x -C "$ctx"
  fi
  _schemaf_check_lockfiles "$ctx" "$dirty" "$short"
  _schemaf_container build -f "$ctx/Dockerfile.gen" -t "$BUILT_IMAGE" \
    --label "schemaf.project=$PROJECT_NAME" \
    --label "schemaf.commit=$commit" \
    --label "schemaf.describe=$describe" \
    --label "schemaf.version=$SCHEMAF_VER" \
    --label "schemaf.dirty=$dirty" \
    "$ctx"
  echo "Built $BUILT_IMAGE" >&2
  [ -z "$output" ] || _schemaf_write_artifact "$output" "$tag" "$commit" "$describe"
}

# _schemaf_check_lockfiles <ctx> <dirty> <short>
# The image gets exactly what the lockfiles pin (npm ci, go build
# -mod=readonly), so a missing one stops the build before the image build.
# ctx is what the image is built from: the commit, or the working tree when dirty.
# See INSTALL.md › Lockfiles.
_schemaf_check_lockfiles() {
  local ctx="$1" dirty="$2" short="$3" where="" hint
  [ "$dirty" = true ] || where=" in commit $short"
  _schemaf_lockfile_missing() {
    hint=""
    if [ "$dirty" = false ] && [ -e "$PROJECT_ROOT/$1" ]; then hint=" (is it gitignored?)"; fi
    _die "$1 is missing$where$hint — build $2. Run $3 and commit $4"
  }
  [ -f "$ctx/go/go.sum" ] || _schemaf_lockfile_missing go/go.sum \
    "compiles exactly what it pins (go build -mod=readonly)" "go mod tidy in go/" "go/go.mod and go/go.sum"
  if [ -f "$ctx/frontend/package.json" ] && [ ! -f "$ctx/frontend/package-lock.json" ]; then
    _schemaf_lockfile_missing frontend/package-lock.json \
      "installs exactly what it pins (npm ci)" "npm install in frontend/" "frontend/package-lock.json"
  fi
}

# The self-extracting header of a deployment artifact. Everything after the
# marker line is a gzipped tar; `load` hands it to the archive's own schemaf.sh.
_schemaf_artifact_header() {
  echo '#!/bin/bash'
  echo "# ${PROJECT_NAME} deployment artifact, built by schemaf. Run: ./$(basename "$1") load"
  echo "# See INSTALL.md › Deployment. Everything below the marker line is a gzipped tar."
  cat <<'HEADER'
set -euo pipefail
if [ $# -ne 1 ] || [ "$1" != load ]; then
  echo "usage: $0 load" >&2
  echo "  loads this build into the current user's container store and installs ~/.<name>/bin/schemaf.sh" >&2
  exit 2
fi
tmp=$(mktemp -d "${TMPDIR:-/tmp}/schemaf-load.XXXXXX")
trap 'rm -rf "$tmp"' EXIT
line=$(awk '/^__SCHEMAF_ARCHIVE__$/ { print NR + 1; exit }' "$0")
tail -n +"$line" "$0" | tar -xz -C "$tmp"
bash "$tmp/schemaf.sh" __load "$tmp"
exit 0
__SCHEMAF_ARCHIVE__
HEADER
}

# _schemaf_write_artifact <output> <tag> <commit> <describe>
_schemaf_write_artifact() {
  local output="$1" tag="$2" commit="$3" describe="$4" stage src paths partial f platform
  echo "Writing $output..." >&2
  stage=$(_schemaf_mktemp)
  _schemaf_container save -o "$stage/image.tar" "$BUILT_IMAGE"
  platform=$(_schemaf_container image inspect --format "${_O}.Os${_C}/${_O}.Architecture${_C}" "$BUILT_IMAGE")
  # Compose files from exactly the commit, like the image: an ignored file in
  # the working tree (which doesn't make it dirty) never ships.
  git cat-file -e "$commit:./compose.gen.yml" 2>/dev/null \
    || _die "compose.gen.yml is not in commit ${commit:0:7} — run ./schemaf.sh codegen and commit it"
  paths="compose.gen.yml"
  if git cat-file -e "$commit:./compose" 2>/dev/null; then paths="$paths compose"; fi
  src=$(_schemaf_mktemp)
  git archive "$commit" $paths | tar -x -C "$src"
  mkdir "$stage/compose"
  cp "$src/compose.gen.yml" "$stage/compose.gen.yml"
  for f in "$src"/compose/*.yml; do
    [ -f "$f" ] || continue
    case "$f" in *.dev.yml) continue ;; esac
    cp "$f" "$stage/compose/"
  done
  cp schemaf.sh "$stage/schemaf.sh"
  {
    echo "name=$PROJECT_NAME"
    echo "tag=$tag"
    echo "commit=$commit"
    echo "describe=$describe"
    echo "schemaf_version=$SCHEMAF_VER"
    echo "platform=$platform"
    echo "port=$PROJECT_PORT"
  } > "$stage/manifest"
  partial=$(mktemp "${output}.XXXXXX")
  { _schemaf_artifact_header "$output"; tar -cz -C "$stage" .; } > "$partial"
  chmod 755 "$partial"
  mv "$partial" "$output"
  echo "Wrote $output — on the run host: $(basename "$output") load" >&2
}

# --- load (run side, called by an artifact's header) --------------------------

# _schemaf_version_cmp <a> <b> — prints -1, 0 or 1 as schemaf version a is
# older than, equal to or newer than b, by semver precedence: vMAJOR.MINOR.PATCH
# with an optional -pre-release (Go pseudo-versions included) and +build. The
# numbers compare numerically, a pre-release is older than its release, build
# metadata is ignored. Anything else fails.
_schemaf_version_cmp() {
  local re='^v([0-9]+)\.([0-9]+)\.([0-9]+)(-([0-9A-Za-z.-]+))?(\+[0-9A-Za-z.-]+)?$'
  local a b ap bp i
  [[ "$1" =~ $re ]] || { echo "ERROR: \"$1\" is not a schemaf version (vX.Y.Z)" >&2; return 1; }
  a="${BASH_REMATCH[1]} ${BASH_REMATCH[2]} ${BASH_REMATCH[3]}" ap="${BASH_REMATCH[5]}"
  [[ "$2" =~ $re ]] || { echo "ERROR: \"$2\" is not a schemaf version (vX.Y.Z)" >&2; return 1; }
  b="${BASH_REMATCH[1]} ${BASH_REMATCH[2]} ${BASH_REMATCH[3]}" bp="${BASH_REMATCH[5]}"
  set -- $a $b
  for i in 1 2 3; do
    if ((10#$1 != 10#$4)); then ((10#$1 > 10#$4)) && echo 1 || echo -1; return 0; fi
    shift
  done
  if [ "$ap" = "$bp" ]; then echo 0
  elif [ -z "$ap" ]; then echo 1
  elif [ -z "$bp" ]; then echo -1
  else _schemaf_prerelease_cmp "$ap" "$bp"
  fi
}

# _schemaf_prerelease_cmp <a> <b> — semver precedence of two different
# pre-releases: dot-separated identifiers left to right, numeric ones
# numerically and below alphanumeric ones, others byte-wise; when one is a
# prefix of the other, the shorter is older.
_schemaf_prerelease_cmp() {
  local a="$1." b="$2." x y num='^[0-9]+$' LC_ALL=C
  while [ -n "$a" ] && [ -n "$b" ]; do
    x="${a%%.*}" y="${b%%.*}" a="${a#*.}" b="${b#*.}"
    [ "$x" != "$y" ] || continue
    if [[ "$x" =~ $num ]] && [[ "$y" =~ $num ]]; then
      ((10#$x > 10#$y)) && echo 1 || echo -1
    elif [[ "$x" =~ $num ]]; then echo -1
    elif [[ "$y" =~ $num ]]; then echo 1
    elif [[ "$x" > "$y" ]]; then echo 1
    else echo -1
    fi
    return 0
  done
  [ -n "$a" ] && echo 1 || echo -1
}

# _schemaf_script_version <schemaf.sh> — the schemaf version on its SCHEMAF_VER line.
_schemaf_script_version() {
  awk -F'"' '/^SCHEMAF_VER="/ { print $2; exit }' "$1"
}

# _schemaf_load <extracted archive dir>
_schemaf_load() {
  local dir="$1" m name tag commit platform host img have dest old ver script installed keep=""
  m="$dir/manifest"
  for f in manifest image.tar schemaf.sh compose.gen.yml; do
    [ -f "$dir/$f" ] || _die "the archive has no $f — it is not a schemaf deployment artifact, or it is damaged"
  done
  name=$(_schemaf_manifest_get "$m" name)
  tag=$(_schemaf_manifest_get "$m" tag)
  commit=$(_schemaf_manifest_get "$m" commit)
  platform=$(_schemaf_manifest_get "$m" platform)
  ver=$(_schemaf_manifest_get "$m" schemaf_version)
  [ "$name" = "$PROJECT_NAME" ] || _die "the manifest names project \"$name\", its schemaf.sh \"$PROJECT_NAME\" — the archive is damaged"
  _schemaf_check_tag "$tag"
  [ -n "$commit" ] || _die "the manifest names no commit — the archive is damaged"

  _schemaf_load_env "$USER_DIR/etc/env"
  _schemaf_check_runtime
  host=$(_schemaf_host_platform)
  [ "$platform" = "$host" ] || _die "this archive's image is for $platform, this host runs $host — build it on a $host machine"

  img="${PROJECT_NAME}:${tag}"
  dest="$DEPLOY_DIR/$tag"
  if _schemaf_image_exists "$img"; then
    have=$(_schemaf_image_label "$img" schemaf.commit)
    [ -n "$have" ] || _die "$img exists but wasn't built by schemaf (it has no schemaf.commit label) — remove that image first"
  elif [ -f "$dest/manifest" ]; then
    have=$(_schemaf_manifest_get "$dest/manifest" commit)
  else
    have=""
  fi
  if [ -n "$have" ] && [ "$have" != "$commit" ]; then
    _die "$tag is already loaded from commit ${have:0:7}, this archive is commit ${commit:0:7} — remove it first (schemaf.sh image rm $tag) or build with a different tag"
  fi
  if [ -n "$have" ] && _schemaf_image_exists "$img" && [ -f "$dest/manifest" ]; then
    echo "$tag is already loaded (commit ${commit:0:7}) — nothing to do" >&2
    echo "$tag"
    return 0
  fi

  # The run-side script: newest wins. An older artifact keeps the installed
  # script, which runs older deploy dirs too (INSTALL.md › Deployment › load).
  script="$USER_DIR/bin/schemaf.sh"
  if [ -f "$script" ]; then
    installed=$(_schemaf_script_version "$script")
    [ -n "$installed" ] || _die "$script names no schemaf version (no SCHEMAF_VER line) — remove it, then load again"
    case "$(_schemaf_version_cmp "$ver" "$installed")" in
      -1) keep="$installed" ;;
      0|1) ;;
      *) _die "can't compare this archive's schemaf version \"$ver\" with the installed script's \"$installed\" — build the artifact from a released schemaf version (vX.Y.Z in go/go.mod), or remove $script, then load again" ;;
    esac
  fi

  if ! _schemaf_image_exists "$img"; then
    echo "Loading $img..." >&2
    _schemaf_container load -i "$dir/image.tar" >&2
    have=$(_schemaf_image_label "$img" schemaf.commit 2>/dev/null) || have=""
    [ "$have" = "$commit" ] || _die "loading the archive did not produce $img from commit ${commit:0:7}"
  fi

  mkdir -p "$DEPLOY_DIR"
  old=$(_schemaf_mktemp)
  mkdir "$old/new"
  cp "$dir/compose.gen.yml" "$dir/manifest" "$old/new/"
  cp -R "$dir/compose" "$old/new/compose"
  rm -rf "$dest"
  mv "$old/new" "$dest"

  if [ -n "$keep" ]; then
    echo "keeping run-side schemaf.sh $keep (artifact has $ver)" >&2
  else
    mkdir -p "$USER_DIR/bin"
    cp "$dir/schemaf.sh" "$old/schemaf.sh"
    chmod 755 "$old/schemaf.sh"
    mv "$old/schemaf.sh" "$script"
  fi
  echo "Loaded $img; start it with: ~/.${PROJECT_NAME}/bin/schemaf.sh run --image $tag" >&2
  echo "$tag"
}

# --- run side -----------------------------------------------------------------

_schemaf_runside_usage() {
  cat >&2 <<EOF
usage: ~/.${PROJECT_NAME}/bin/schemaf.sh <command>   (run side: no checkout on this host)
  run --image <tag> [flags]   start a loaded image (flags go to compose up, e.g. -d)
  stop                        stop the stack
  status                      list the stack's containers
  logs [flags]                show the stack's logs (flags go to compose logs, e.g. -f backend)
  image ls                    loaded tags
  image rm <tag>              remove a loaded tag (not the running one)
  releases                    download and verify the releases newer than the running one (Linux)
  install <version>           install a verified release, with backup and rollback (Linux)
  updater enable|disable|status   the units that let the app request an upgrade (Linux)
  <app subcommand> ...        run in the backend container, e.g. db backup
See INSTALL.md › Deployment.
EOF
}

# _schemaf_compose_current <compose args...> — compose on the stack's current
# deployment (the tag of the existing backend container).
_schemaf_compose_current() {
  local b tag
  b=$(_schemaf_backend)
  [ -n "$b" ] || return 3
  tag="${b#* }"
  [ -f "$DEPLOY_DIR/$tag/compose.gen.yml" ] || _die "the backend runs $tag, but $DEPLOY_DIR/$tag/ is missing"
  export SCHEMAF_IMAGE="${PROJECT_NAME}:${tag}"
  _schemaf_container --exec compose -f "$DEPLOY_DIR/$tag/compose.gen.yml" "$@"
}

# _schemaf_run_image <tag> [compose up flags] — start a loaded tag; replaces
# this process with compose (run --image). _schemaf_start_image does the same
# and returns (install).
_schemaf_run_image() { _SCHEMAF_START_EXEC=--exec _schemaf_start_image "$@"; }

_schemaf_start_image() {
  local tag="$1" img dest labelled deployed
  shift
  _schemaf_check_tag "$tag"
  _schemaf_check_runtime compose
  _schemaf_check_volume
  img="${PROJECT_NAME}:${tag}"
  dest="$DEPLOY_DIR/$tag"
  _schemaf_updates_files || _die "could not create $UPDATES_DIR (the backend mounts it)"
  _schemaf_image_exists "$img" || _die "$img is not loaded — load its artifact first (./${PROJECT_NAME}-${tag}.run load); loaded tags: schemaf.sh image ls"
  [ -f "$dest/compose.gen.yml" ] && [ -f "$dest/manifest" ] || _die "$dest/ is missing — load the artifact again (./${PROJECT_NAME}-${tag}.run load)"
  labelled=$(_schemaf_image_label "$img" schemaf.commit)
  deployed=$(_schemaf_manifest_get "$dest/manifest" commit)
  [ "$labelled" = "$deployed" ] || _die "$img is commit ${labelled:0:7}, but $dest/ is commit ${deployed:0:7} — remove the tag (schemaf.sh image rm $tag) and load it again"
  export SCHEMAF_IMAGE="$img"
  _schemaf_container ${_SCHEMAF_START_EXEC:-} compose -f "$dest/compose.gen.yml" up "$@"
}

_schemaf_image_ls() {
  local d tag img commit describe size running mark any=0
  running=$(_schemaf_running_tag)
  printf '%-24s %-9s %-28s %-8s %s\n' TAG COMMIT DESCRIBE SIZE RUNNING
  for d in "$DEPLOY_DIR"/*/; do
    [ -f "$d/manifest" ] || continue
    any=1
    tag=$(basename "$d")
    img="${PROJECT_NAME}:${tag}"
    commit=$(_schemaf_manifest_get "$d/manifest" commit)
    describe=$(_schemaf_manifest_get "$d/manifest" describe)
    if _schemaf_image_exists "$img"; then
      size=$(_schemaf_container image inspect --format "${_O}.Size${_C}" "$img" \
        | awk '{ s = $1; split("B KB MB GB TB", u, " "); i = 1; while (s >= 1024 && i < 5) { s /= 1024; i++ } printf "%.0f%s", s, u[i] }')
    else
      size="missing"
    fi
    mark=""
    [ "$tag" != "$running" ] || mark="*"
    printf '%-24s %-9s %-28s %-8s %s\n' "$tag" "${commit:0:7}" "$describe" "$size" "$mark"
  done
  [ "$any" = 1 ] || echo "No tags loaded — load an artifact: ./${PROJECT_NAME}-<tag>.run load" >&2
}

_schemaf_image_rm() {
  local tag="$1" img b
  _schemaf_check_tag "$tag"
  img="${PROJECT_NAME}:${tag}"
  b=$(_schemaf_backend)
  if [ -n "$b" ] && [ "${b#* }" = "$tag" ]; then
    if [ "${b%% *}" = true ]; then
      _die "$tag is running — start another tag first (schemaf.sh run --image <tag>), or stop it (schemaf.sh stop)"
    fi
    _die "$tag is used by the stopped ${PROJECT_NAME}-backend container — remove it first: schemaf.sh stop"
  fi
  if ! _schemaf_image_exists "$img" && [ ! -d "$DEPLOY_DIR/$tag" ]; then
    _die "$tag is not loaded (loaded tags: schemaf.sh image ls)"
  fi
  if _schemaf_image_exists "$img"; then
    _schemaf_container image rm "$img" >/dev/null
  fi
  rm -rf "$DEPLOY_DIR/$tag"
  echo "Removed $tag" >&2
}

# --instance is dev-only (INSTALL.md › Parallel dev instances): production
# always runs the one production stack. _schemaf_refuse_instance <cmd> <args...>
_schemaf_refuse_instance() {
  local cmd="$1" a
  shift
  for a in "$@"; do
    case "$a" in
      --instance|--instance=*) _die "--instance is dev-only: $cmd always uses the one production stack (a parallel dev stack: ./schemaf.sh dev all --instance <n>)" ;;
    esac
  done
}

_schemaf_runside() {
  local cmd="$1" b tty
  shift
  _schemaf_load_env "$USER_DIR/etc/env"
  unset SCHEMAF_DEV # the run side is production, even if the caller's shell exports it
  case "$cmd" in
    run)
      _schemaf_refuse_instance run "$@"
      [ "${1:-}" = --image ] && [ $# -ge 2 ] || _die "on the run side, run needs a tag: schemaf.sh run --image <tag> (loaded tags: schemaf.sh image ls)"
      local tag="$2"
      shift 2
      _schemaf_run_image "$tag" "$@"
      ;;
    stop)
      _schemaf_check_runtime compose
      _schemaf_compose_current down "$@" || { [ $? = 3 ] && echo "Nothing to stop: there is no ${PROJECT_NAME}-backend container" >&2; }
      ;;
    status)
      _schemaf_check_runtime compose
      _schemaf_compose_current ps "$@" || { [ $? = 3 ] && echo "Not running: there is no ${PROJECT_NAME}-backend container" >&2; }
      ;;
    logs)
      _schemaf_check_runtime compose
      _schemaf_compose_current logs "$@" || { [ $? = 3 ] && _die "no logs: there is no ${PROJECT_NAME}-backend container (start it: schemaf.sh run --image <tag>)"; }
      ;;
    releases)
      [ $# -eq 0 ] || _die "usage: schemaf.sh releases"
      _schemaf_releases
      ;;
    install)
      _schemaf_install "$@"
      ;;
    updater)
      _schemaf_updater "$@"
      ;;
    image)
      _schemaf_check_runtime
      case "${1:-}" in
        ls) _schemaf_image_ls ;;
        rm) [ $# -eq 2 ] || _die "usage: schemaf.sh image rm <tag>"; _schemaf_image_rm "$2" ;;
        *) _die "usage: schemaf.sh image ls | image rm <tag>" ;;
      esac
      ;;
    codegen|test|dev|build|upgrade)
      _die "$NO_CHECKOUT"
      ;;
    server)
      _die "the server runs in the backend container — start it with: schemaf.sh run --image <tag>"
      ;;
    ""|-h|--help|help)
      _schemaf_runside_usage
      ;;
    *)
      # An app subcommand: run it in exactly the deployed version.
      _schemaf_check_runtime
      [ -n "$(_schemaf_running_tag)" ] || _die "start it first: schemaf.sh run --image <tag> (loaded tags: schemaf.sh image ls)"
      tty="-i"
      if [ -t 0 ] && [ -t 1 ]; then tty="-it"; fi
      _schemaf_container --exec exec "$tty" "${PROJECT_NAME}-backend" /app "$cmd" "$@"
      ;;
  esac
}

# --- pull: releases and install (run side, Linux) ----------------------------
# See INSTALL.md › Pulling releases. The tools run in containers pinned by
# digest, so the run host needs nothing but the container runtime.

SCHEMAF_IMG_CURL="docker.io/curlimages/curl:8.23.0@sha256:3fb7e13e5d179a845c97d78204f3f1064d1907037f26a3ebf91710571151fd93"
SCHEMAF_IMG_JQ="ghcr.io/jqlang/jq:1.8.2@sha256:b9c68867e5766576263a222e91db3de422d802069c7af70440e667a95344e486"
SCHEMAF_IMG_COSIGN="ghcr.io/sigstore/cosign/cosign:v3.1.4@sha256:0f06154836d2de34f887a5c273506d52ca43edaa1d9e53e6510fa78a48f69c2d"
SCHEMAF_GITHUB_ISSUER="https://token.actions.githubusercontent.com"
# 120 seconds; _SCHEMAF_TEST_HEALTH_TIMEOUT exists for schemaf's own tests only.
SCHEMAF_HEALTH_TIMEOUT="${_SCHEMAF_TEST_HEALTH_TIMEOUT:-120}"
RELEASES_DIR="$USER_DIR/releases"
UPDATES_DIR="$USER_DIR/updates"
VAR_DIR="$USER_DIR/var"

# _schemaf_try <command...> — runs it in a subshell and returns its status, so
# a _die inside ends only the subshell and install can always roll back. It is
# called in conditions, where errexit is off, so every step it runs returns its
# failures explicitly (|| return 1).
_schemaf_try() {
  ( "$@" )
}

_schemaf_pull_linux_only() {
  [ "$(uname)" = Linux ] || _die "the pull flow (releases, install) runs on Linux only — on macOS use build --output, load and run --image (INSTALL.md › Deployment)"
}

# _schemaf_is_version <v> — X.Y.Z or X.Y.Z-<pre> (dot-separated, non-empty
# identifiers), as release tags without the v.
_schemaf_is_version() {
  local num='(0|[1-9][0-9]*)' id='[0-9A-Za-z-]+'
  [[ "$1" =~ ^$num\.$num\.$num(-$id(\.$id)*)?$ ]]
}

# _schemaf_newer <a> <b> — version a is newer than b (semver precedence).
_schemaf_newer() { [ "$(_schemaf_version_cmp "v$1" "v$2")" = 1 ]; }

# _schemaf_pull_config — checks the pull settings from ~/.<name>/etc/env and
# sets SIGNER_REPO or SIGNER_IDENTITY, and SIGNER_ISSUER.
_schemaf_pull_config() {
  local env="$USER_DIR/etc/env"
  [ -n "${SCHEMAF_RELEASES:-}" ] || _die "SCHEMAF_RELEASES is not set — set it in $env to the URL of the app's releases.json (INSTALL.md › Pulling releases)"
  [[ "$SCHEMAF_RELEASES" =~ ^https?://[^[:space:]]+$ ]] || _die "SCHEMAF_RELEASES=\"$SCHEMAF_RELEASES\" is not an http(s) URL"
  [ -n "${SCHEMAF_SIGNER:-}" ] || _die "SCHEMAF_SIGNER is not set — set it in $env to <owner>/<repo> of the app's repository, or a full certificate identity (INSTALL.md › Pulling releases)"
  SIGNER_ISSUER="${SCHEMAF_SIGNER_ISSUER:-$SCHEMAF_GITHUB_ISSUER}"
  SIGNER_REPO="" SIGNER_IDENTITY=""
  if [[ "$SCHEMAF_SIGNER" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]]; then
    [ -z "${SCHEMAF_SIGNER_ISSUER:-}" ] || _die "SCHEMAF_SIGNER_ISSUER goes with a full certificate identity in SCHEMAF_SIGNER; with <owner>/<repo> the issuer is always GitHub Actions"
    SIGNER_REPO="$SCHEMAF_SIGNER"
  elif [[ "$SCHEMAF_SIGNER" =~ ^https://[^[:space:]]+$ ]]; then
    SIGNER_IDENTITY="$SCHEMAF_SIGNER"
  else
    _die "SCHEMAF_SIGNER=\"$SCHEMAF_SIGNER\" is neither <owner>/<repo> nor a full certificate identity (https://...)"
  fi
  case "${SCHEMAF_CHANNEL:-}" in
    stable|prerelease) ;;
    "") _die "SCHEMAF_CHANNEL is not set — set it in $env to stable or prerelease" ;;
    *) _die "SCHEMAF_CHANNEL=\"$SCHEMAF_CHANNEL\" is not a channel — use stable or prerelease" ;;
  esac
}

# _schemaf_on_channel <version>
_schemaf_on_channel() {
  [ "$SCHEMAF_CHANNEL" = prerelease ] || [[ "$1" != *-* ]]
}

# _schemaf_running_version — the running tag, which must be a version; empty
# when nothing runs.
_schemaf_running_version() {
  local tag
  tag=$(_schemaf_running_tag)
  [ -z "$tag" ] || _schemaf_is_version "$tag" || _die "the running tag $tag is not a release version — the pull flow compares versions; start a release first (run --image <version>), or stop the stack for a first install"
  echo "$tag"
}

_schemaf_fetch() { # <url> <file>
  _schemaf_container run --rm --network host "$SCHEMAF_IMG_CURL" -fsSL --proto '=https,http' "$1" > "$2"
}

_schemaf_jq() { # <jq args...>, stdin → stdout
  _schemaf_container run --rm -i "$SCHEMAF_IMG_JQ" "$@"
}

# _schemaf_verify <dir> <artifact file> <bundle file> <version> — the bundle
# attests the artifact, signed by the configured signer (INSTALL.md › The settings).
_schemaf_verify() {
  local dir="$1" art="$2" bundle="$3" version="$4" identity out
  identity="$SIGNER_IDENTITY"
  [ -n "$identity" ] || identity="https://github.com/$SIGNER_REPO/.github/workflows/release.gen.yml@refs/tags/v$version"
  chmod 755 "$dir" || return 1
  chmod 644 "$dir/$art" "$dir/$bundle" || return 1
  if ! out=$(_schemaf_container run --rm --network host --user 0:0 -v "$dir:/w:ro" "$SCHEMAF_IMG_COSIGN" \
      verify-blob-attestation --bundle "/w/$bundle" --type slsaprovenance1 \
      --certificate-identity "$identity" --certificate-oidc-issuer "$SIGNER_ISSUER" "/w/$art" 2>&1); then
    echo "$out" | sed 's/^/    /' >&2
    return 1
  fi
}

# _schemaf_artifact_manifest <artifact> — prints the artifact's manifest.
_schemaf_artifact_manifest() {
  local line
  line=$(awk '/^__SCHEMAF_ARCHIVE__$/ { print NR + 1; exit }' "$1")
  [ -n "$line" ] || return 1
  tail -n +"$line" "$1" | tar -xzO ./manifest
}

# _schemaf_index <file> — validates releases.json and prints one line per
# entry: <version> <artifact url> <attestation url>.
_schemaf_index() {
  local out v art att err="$1.err"
  out=$(_schemaf_jq -r '
    if type != "array" then error("not a list") else . end
    | map(if type == "object" and (.version | type) == "string" and (.artifact | type) == "string" and (.attestation | type) == "string"
          then . else error("an entry without string version, artifact and attestation: \(tojson)") end)
    | if (map(.version) | length) != (map(.version) | unique | length) then error("a version is listed twice") else . end
    | .[] | "\(.version) \(.artifact) \(.attestation)"' < "$1" 2>"$err") \
    || _die "$SCHEMAF_RELEASES is not a valid release index: $(tail -n 3 "$err")"
  while read -r v art att; do
    [ -n "$v" ] || continue
    _schemaf_is_version "$v" || _die "$SCHEMAF_RELEASES lists \"$v\", which is not a version (X.Y.Z or X.Y.Z-<pre>)"
    [[ "$art" =~ ^https?://[^[:space:]]+$ ]] && [[ "$att" =~ ^https?://[^[:space:]]+$ ]] || _die "$SCHEMAF_RELEASES: version $v has no http(s) URLs for artifact and attestation"
    echo "$v $art $att"
  done <<< "$out"
}

# _schemaf_sort_versions — reads versions (one per line), prints them oldest first.
_schemaf_sort_versions() {
  local sorted="" v w out inserted
  while read -r v; do
    [ -n "$v" ] || continue
    out="" inserted=0
    for w in $sorted; do
      if [ "$inserted" = 0 ] && _schemaf_newer "$w" "$v"; then out="$out $v"; inserted=1; fi
      out="$out $w"
    done
    [ "$inserted" = 1 ] || out="$out $v"
    sorted="$out"
  done
  for v in $sorted; do echo "$v"; done
}

# _schemaf_download <tmp> <version> <artifact url> <attestation url> — downloads,
# verifies and checks the manifest; keeps the files only if all of it passes.
_schemaf_download() {
  local tmp="$1" v="$2" art_url="$3" att_url="$4" art bundle m name tag
  art="${PROJECT_NAME}-${v}.run" bundle="${PROJECT_NAME}-${v}.run.sigstore.json"
  echo "  $v: downloading" >&2
  _schemaf_fetch "$art_url" "$tmp/$art" || { echo "ERROR: $v: could not download $art_url" >&2; return 1; }
  _schemaf_fetch "$att_url" "$tmp/$bundle" || { echo "ERROR: $v: could not download $att_url" >&2; return 1; }
  if ! _schemaf_verify "$tmp" "$art" "$bundle" "$v"; then
    echo "ERROR: $v: the attestation does not verify for signer $SCHEMAF_SIGNER — deleted, not kept" >&2
    return 1
  fi
  if ! m=$(_schemaf_artifact_manifest "$tmp/$art"); then
    echo "ERROR: $v: $art is not a schemaf artifact — deleted, not kept" >&2
    return 1
  fi
  name=$(_schemaf_manifest_get <(echo "$m") name) || return 1
  tag=$(_schemaf_manifest_get <(echo "$m") tag) || return 1
  if [ "$name" != "$PROJECT_NAME" ] || [ "$tag" != "$v" ]; then
    echo "ERROR: $v: the artifact's manifest names $name $tag, the index says $PROJECT_NAME $v — deleted, not kept" >&2
    return 1
  fi
  mkdir -p "$RELEASES_DIR" "$tmp/keep" || return 1
  rm -rf "${RELEASES_DIR:?}/${v:?}" || return 1
  mv "$tmp/$art" "$tmp/$bundle" "$tmp/keep/" || return 1
  mv "$tmp/keep" "$RELEASES_DIR/$v" || return 1
  echo "  $v: verified" >&2
}

_schemaf_releases() {
  local running index entries newest="" v art att failed=0 wanted=""
  _schemaf_pull_linux_only
  _schemaf_pull_config
  _schemaf_check_runtime
  _schemaf_clear_stale_install
  running=$(_schemaf_running_version) || exit 1
  index="$(_schemaf_mktemp)/releases.json"
  echo "Fetching $SCHEMAF_RELEASES (channel $SCHEMAF_CHANNEL, running ${running:-nothing})" >&2
  _schemaf_fetch "$SCHEMAF_RELEASES" "$index" || _die "could not download $SCHEMAF_RELEASES"
  entries=$(_schemaf_index "$index") || exit 1
  if [ -z "$running" ]; then
    # A first install takes the newest version on the channel, nothing older.
    newest=$(while read -r v _; do [ -z "$v" ] || ! _schemaf_on_channel "$v" || echo "$v"; done <<< "$entries" | _schemaf_sort_versions | tail -n 1)
  fi
  while read -r v art att; do
    [ -n "$v" ] || continue
    _schemaf_on_channel "$v" || continue
    if [ -n "$running" ]; then _schemaf_newer "$v" "$running" || continue; else [ "$v" = "$newest" ] || continue; fi
    if [ ! -f "$RELEASES_DIR/$v/${PROJECT_NAME}-${v}.run" ]; then
      _schemaf_try _schemaf_download "$(_schemaf_mktemp)" "$v" "$art" "$att" || { failed=1; continue; }
    fi
    wanted="$wanted$v"$'\n'
  done <<< "$entries"
  wanted=$(printf '%s' "$wanted" | _schemaf_sort_versions)
  _schemaf_write_available "$index" "$wanted" || _die "could not write $UPDATES_DIR/available.json"
  [ -z "$wanted" ] || echo "$wanted"
  [ "$failed" = 0 ] || _die "some releases failed their checks (see above)"
}

# --- install state: ~/.<name>/var/state, ~/.<name>/updates/status.json --------

# _schemaf_json_str <string> — as a JSON string literal.
_schemaf_json_str() {
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  s="${s//$'\n'/\\n}"
  s="${s//$'\r'/\\r}"
  s="${s//$'\t'/\\t}"
  printf '"%s"' "$(printf '%s' "$s" | LC_ALL=C tr -d '\000-\010\013\014\016-\037')"
}

_schemaf_state_get() { # <key>
  [ -f "$VAR_DIR/state" ] || return 0
  _schemaf_manifest_get "$VAR_DIR/state" "$1"
}

# _schemaf_record <running> <previous> <version> <from> <state> <started>
#   <finished> <message> <backup> <log> — records the versions and the
#   install, and rewrites status.json.
_schemaf_record() {
  local a i=0
  # One line per value in the state files: no newlines inside.
  for a in "$@"; do i=$((i + 1)); set -- "$@" "${a//$'\n'/ }"; done
  shift "$i"
  mkdir -p "$VAR_DIR"
  printf 'running=%s\nprevious=%s\n' "$1" "$2" > "$VAR_DIR/state.tmp"
  mv "$VAR_DIR/state.tmp" "$VAR_DIR/state"
  printf 'version=%s\nfrom=%s\nstate=%s\nstarted=%s\nfinished=%s\nmessage=%s\nbackup=%s\nlog=%s\n' \
    "$3" "$4" "$5" "$6" "$7" "$8" "$9" "${10}" > "$VAR_DIR/install.tmp"
  mv "$VAR_DIR/install.tmp" "$VAR_DIR/install"
  _schemaf_write_status
  if [ "$5" != installing ]; then
    echo "$7 $3 from=${4:--} $5 $8" >> "$VAR_DIR/installs.log"
  fi
}

# _schemaf_status_field <file> <key> — a JSON member of a state file's value.
_schemaf_status_field() {
  local v=""
  [ ! -f "$VAR_DIR/$1" ] || v=$(_schemaf_manifest_get "$VAR_DIR/$1" "$2")
  printf '"%s": %s' "$2" "$(_schemaf_json_str "$v")"
}

# _schemaf_write_status — ~/.<name>/updates/status.json from the state files
# (var/state, var/install, var/request), atomically.
_schemaf_write_status() {
  local tmp="$UPDATES_DIR/.status.json.tmp" k sep
  mkdir -p "$UPDATES_DIR"
  {
    echo "{"
    echo "  $(_schemaf_status_field state running),"
    echo "  $(_schemaf_status_field state previous),"
    echo "  \"install\": {"
    sep=""
    for k in version from state started finished message backup log; do
      printf '%s    %s' "$sep" "$(_schemaf_status_field install "$k")"; sep=$',\n'
    done
    printf '\n  },\n  "request": {\n'
    sep=""
    for k in version state message time; do
      printf '%s    %s' "$sep" "$(_schemaf_status_field request "$k")"; sep=$',\n'
    done
    printf '\n  }\n}\n'
  } > "$tmp"
  chmod 644 "$tmp"
  mv "$tmp" "$UPDATES_DIR/status.json"
}

_schemaf_now() { date -u +%Y-%m-%dT%H:%M:%SZ; }

# --- install --------------------------------------------------------------------

# _schemaf_compose_tag <tag> <compose args...> — compose on that tag's deployment.
_schemaf_compose_tag() {
  local tag="$1"
  shift
  SCHEMAF_IMAGE="${PROJECT_NAME}:${tag}" _schemaf_container compose -f "$DEPLOY_DIR/$tag/compose.gen.yml" "$@"
}

# _schemaf_healthy <tag> — waits for GET /api/health to answer "status": "ok",
# on the port that tag's manifest names (a release may change it).
_schemaf_healthy() {
  local deadline=$((SECONDS + SCHEMAF_HEALTH_TIMEOUT)) out port
  port=$(_schemaf_manifest_get "$DEPLOY_DIR/$1/manifest" port)
  port="${port:-$PROJECT_PORT}" # artifacts from before the port entry
  while :; do
    if out=$(_schemaf_container run --rm --network host "$SCHEMAF_IMG_CURL" -fsS --max-time 5 "http://127.0.0.1:${port}/api/health" 2>/dev/null) \
      && [[ "$out" =~ \"status\"[[:space:]]*:[[:space:]]*\"ok\" ]]; then
      return 0
    fi
    [ "$SECONDS" -lt "$deadline" ] || break
    sleep 2
  done
  echo "ERROR: no healthy answer from http://127.0.0.1:${port}/api/health within ${SCHEMAF_HEALTH_TIMEOUT}s" >&2
  return 1
}

_schemaf_backup() { # <file>
  _schemaf_container exec "${PROJECT_NAME}-postgres" pg_dump -U schemaf -d "$PROJECT_NAME" -Fc > "$1" || return 1
  [ -s "$1" ]
}

# _schemaf_restore <file> — recreates the database from the backup, so nothing
# the failed version created survives.
_schemaf_restore() {
  _schemaf_container exec "${PROJECT_NAME}-postgres" psql -U schemaf -d postgres -v ON_ERROR_STOP=1 -q \
    -c "DROP DATABASE IF EXISTS \"$PROJECT_NAME\" WITH (FORCE)" \
    -c "CREATE DATABASE \"$PROJECT_NAME\" OWNER schemaf" || return 1
  _schemaf_container exec -i "${PROJECT_NAME}-postgres" pg_restore -U schemaf -d "$PROJECT_NAME" --exit-on-error < "$1"
}

_schemaf_load_artifact() { # <artifact>
  bash "$1" load >/dev/null
}

# _schemaf_prune <running> <previous> — retention after a successful install:
# keeps running, previous and downloaded versions newer than running.
_schemaf_prune() {
  local running="$1" previous="$2" d v
  for d in "$DEPLOY_DIR"/*/ "$RELEASES_DIR"/*/; do
    [ -d "$d" ] || continue
    v=$(basename "$d")
    _schemaf_is_version "$v" || continue # tags loaded by hand are never removed
    [ "$v" != "$running" ] && [ "$v" != "$previous" ] || continue
    case "$d" in
      "$RELEASES_DIR"/*) if _schemaf_newer "$v" "$running"; then continue; fi ;;
      *)
        if _schemaf_image_exists "${PROJECT_NAME}:${v}"; then
          _schemaf_container image rm "${PROJECT_NAME}:${v}" >/dev/null || echo "  could not remove the image ${PROJECT_NAME}:${v}" >&2
        fi
        ;;
    esac
    rm -rf "${d:?}"
    echo "  pruned $d" >&2
  done
}

# _schemaf_prune_backups <keep> — removes the backups other than <keep>.
_schemaf_prune_backups() {
  local f
  for f in "$VAR_DIR/backups"/*; do
    [ -f "$f" ] && [ "$f" != "$1" ] || continue
    rm -f "${f:?}"
  done
}

# _schemaf_install_lock — one install at a time: a lock directory holding the
# owner's PID, removed on exit (it joins the temporary directories). A lock
# whose owner is gone is stale and taken over. (Not flock: its file descriptor
# would be inherited by the long-lived processes podman starts.)
_schemaf_install_lock() {
  local lock="$VAR_DIR/install.lock" pid
  mkdir -p "$VAR_DIR"
  if ! mkdir "$lock" 2>/dev/null; then
    pid=$(cat "$lock/pid" 2>/dev/null || true)
    if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
      _die "another install is running (PID $pid) — try again when it has finished (status: $UPDATES_DIR/status.json)"
    fi
    echo "  taking over a stale install lock (PID ${pid:-unknown} is gone)" >&2
    rm -rf "${lock:?}"
    mkdir "$lock" 2>/dev/null || _die "another install took the lock just now — try again when it has finished"
  fi
  echo "$$" > "$lock/pid"
  _SCHEMAF_TMP="$_SCHEMAF_TMP $lock"
}

_schemaf_install() {
  local v="${1:-}" running previous dir art bundle started backup="" log="" msg
  [ $# -eq 1 ] || _die "usage: schemaf.sh install <version>"
  _schemaf_pull_linux_only
  _schemaf_pull_config
  _schemaf_is_version "$v" || _die "\"$v\" is not a version (X.Y.Z or X.Y.Z-<pre>)"
  _schemaf_check_runtime compose
  _schemaf_check_volume
  _schemaf_install_lock

  running=$(_schemaf_running_version) || exit 1
  _schemaf_on_channel "$v" || _die "$v is a prerelease, and this host's channel is stable (SCHEMAF_CHANNEL)"
  [ -z "$running" ] || _schemaf_newer "$v" "$running" || _die "$v is not newer than the running $running — install only goes forward (a manual rollback: schemaf.sh run --image <older tag>)"
  dir="$RELEASES_DIR/$v" art="${PROJECT_NAME}-${v}.run" bundle="${PROJECT_NAME}-${v}.run.sigstore.json"
  [ -f "$dir/$art" ] && [ -f "$dir/$bundle" ] || _die "$v is not downloaded — run schemaf.sh releases first (it downloads and verifies the versions newer than the running one)"
  _schemaf_verify "$dir" "$art" "$bundle" "$v" || _die "$v: the attestation of $dir/$art does not verify for signer $SCHEMAF_SIGNER — remove $dir and run schemaf.sh releases again"
  previous=$(_schemaf_state_get previous)
  [ -n "$running" ] || previous=""
  started=$(_schemaf_now)
  _schemaf_record "$running" "$previous" "$v" "$running" installing "$started" "" "installing $v" "" ""

  echo "Installing $v (running: ${running:-nothing})" >&2
  echo "  load $art" >&2
  if ! _schemaf_try _schemaf_load_artifact "$dir/$art"; then
    msg="loading $art failed; nothing changed"
    _schemaf_record "$running" "$previous" "$v" "$running" failed "$started" "$(_schemaf_now)" "$msg" "" ""
    _die "$msg"
  fi

  if [ -n "$running" ]; then
    echo "  stop the backend, back up the database" >&2
    mkdir -p "$VAR_DIR/backups"
    backup="$VAR_DIR/backups/${running}-$(date -u +%Y%m%dT%H%M%SZ).dump"
    if ! _schemaf_try _schemaf_compose_tag "$running" stop backend || ! _schemaf_try _schemaf_backup "$backup"; then
      rm -f "${backup:?}" # a partial dump is no backup
      if _schemaf_try _schemaf_start_image "$running" -d; then
        msg="the database backup failed; $running was started again, nothing changed"
        _schemaf_record "$running" "$previous" "$v" "$running" failed "$started" "$(_schemaf_now)" "$msg" "" ""
      else
        msg="the database backup failed, and starting $running again failed too — the stack is stopped; start it with: schemaf.sh run --image $running -d"
        _schemaf_record "" "$running" "$v" "$running" failed "$started" "$(_schemaf_now)" "$msg" "" ""
      fi
      _die "$msg"
    fi
  fi

  echo "  start $v, wait for its health check" >&2
  if _schemaf_try _schemaf_start_image "$v" -d && _schemaf_healthy "$v"; then
    _schemaf_record "$v" "$running" "$v" "$running" installed "$started" "$(_schemaf_now)" "installed $v" "$backup" ""
    _schemaf_prune "$v" "$running"
    _schemaf_prune_backups "$backup"
    echo "Installed $v" >&2
    return 0
  fi

  mkdir -p "$VAR_DIR/installs"
  log="$VAR_DIR/installs/$(date -u +%Y%m%dT%H%M%SZ)-${v}.log"
  _schemaf_container logs "${PROJECT_NAME}-backend" > "$log" 2>&1 || true
  if [ -z "$running" ]; then
    _schemaf_try _schemaf_compose_tag "$v" down || true
    msg="$v failed its health check; nothing to roll back to, so it is stopped (the database volume is kept); logs: $log"
    _schemaf_record "" "" "$v" "" failed "$started" "$(_schemaf_now)" "$msg" "" "$log"
    _die "$msg"
  fi
  echo "  $v failed its health check — rolling back to $running" >&2
  if _schemaf_try _schemaf_compose_tag "$v" stop backend \
    && _schemaf_try _schemaf_restore "$backup" \
    && _schemaf_try _schemaf_start_image "$running" -d \
    && _schemaf_healthy "$running"; then
    msg="$v failed its health check; rolled back to $running, the database restored from the backup; logs: $log"
    _schemaf_record "$running" "$previous" "$v" "$running" rolled-back "$started" "$(_schemaf_now)" "$msg" "$backup" "$log"
    _die "$msg"
  fi
  _schemaf_try _schemaf_compose_tag "$running" down || true
  msg="$v failed its health check, and the rollback to $running failed too — the stack is stopped. Backup: $backup; logs of $v: $log"
  _schemaf_record "" "$running" "$v" "$running" rollback-failed "$started" "$(_schemaf_now)" "$msg" "$backup" "$log"
  _die "$msg"
}

# --- updater (run side, Linux): systemd user units, the app's request --------
# See INSTALL.md › The updater.

_schemaf_unit_dir() { echo "${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"; }
_schemaf_unit_prefix() { echo "schemaf-${PROJECT_NAME}"; }

# _schemaf_updates_files — what the backend container mounts must exist before
# the stack starts: a missing bind-mount source would become a directory.
_schemaf_updates_files() {
  mkdir -p "$UPDATES_DIR" || return 1
  [ -f "$UPDATES_DIR/request" ] || : > "$UPDATES_DIR/request" || return 1
  chmod 755 "$UPDATES_DIR" && chmod 644 "$UPDATES_DIR/request"
}

# _schemaf_write_available <index file> <versions, oldest first, one per line>
# — ~/.<name>/updates/available.json: the versions with their release notes.
_schemaf_write_available() {
  local index="$1" keep="[" v sep="" tmp="$UPDATES_DIR/.available.json.tmp"
  while read -r v; do
    [ -n "$v" ] || continue
    keep="$keep$sep\"$v\"" sep="," # versions are checked: no quotes inside
  done <<< "$2"
  keep="$keep]"
  mkdir -p "$UPDATES_DIR"
  _schemaf_jq --argjson keep "$keep" --arg checked "$(_schemaf_now)" '. as $all
    | {checked: $checked, versions: [$keep[] as $v | ($all[] | select(.version == $v))
        | {version, notes: ((.notes // "") | if type == "string" then . else tojson end)}]}' \
    < "$index" > "$tmp" 2>"$tmp.err" || { cat "$tmp.err" >&2; rm -f "$tmp" "$tmp.err"; return 1; }
  rm -f "$tmp.err"
  chmod 644 "$tmp"
  mv "$tmp" "$UPDATES_DIR/available.json"
}

# _schemaf_record_request <version> <state> <message> — the last request the
# updater handled, in status.json.
_schemaf_record_request() {
  mkdir -p "$VAR_DIR"
  printf 'version=%s\nstate=%s\nmessage=%s\ntime=%s\n' "${1//$'\n'/ }" "$2" "${3//$'\n'/ }" "$(_schemaf_now)" > "$VAR_DIR/request.tmp"
  mv "$VAR_DIR/request.tmp" "$VAR_DIR/request"
  _schemaf_write_status
  echo "request $1: $2 — $3" >&2
}

# _schemaf_clear_stale_install — an install recorded as installing whose
# process is gone (a reboot, a kill) is recorded as failed, so the app's
# update API doesn't report "installing" forever.
_schemaf_clear_stale_install() {
  local v
  [ "$(_schemaf_state_get_file install state)" = installing ] || return 0
  ! _schemaf_install_running || return 0
  v=$(_schemaf_state_get_file install version)
  _schemaf_record "$(_schemaf_running_tag)" "$(_schemaf_state_get previous)" "$v" \
    "$(_schemaf_state_get_file install from)" failed "$(_schemaf_state_get_file install started)" "$(_schemaf_now)" \
    "the install of $v was interrupted (its process is gone) — check the stack: schemaf.sh status" \
    "$(_schemaf_state_get_file install backup)" ""
  echo "  recorded the interrupted install of $v as failed" >&2
}

_schemaf_state_get_file() { # <file> <key>
  [ -f "$VAR_DIR/$1" ] || return 0
  _schemaf_manifest_get "$VAR_DIR/$1" "$2"
}

# _schemaf_install_running — an install holds the lock (a live PID).
_schemaf_install_running() {
  local pid
  pid=$(cat "$VAR_DIR/install.lock/pid" 2>/dev/null || true)
  [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null
}

# _schemaf_take_request — prints the request file's content and empties it.
_schemaf_take_request() {
  local req
  [ -f "$UPDATES_DIR/request" ] || return 0
  req=$(head -c 256 "$UPDATES_DIR/request" | tr -d '\r') || true
  : > "$UPDATES_DIR/request" # in place: it is a bind mount
  printf '%s' "$req" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' | sed '/^$/d'
}

# _schemaf_updater_request — run by the path unit when the app writes the
# request: untrusted input, one version string. Rejections are recorded and
# exit 0 (a failing path-triggered service would hit systemd's start limit).
_schemaf_updater_request() {
  local req running
  _schemaf_pull_linux_only
  _schemaf_pull_config
  _schemaf_clear_stale_install
  req=$(_schemaf_take_request)
  [ -n "$req" ] || return 0 # the empty file after a read: nothing asked
  if [[ "$req" == *$'\n'* ]] || ! _schemaf_is_version "$req"; then
    _schemaf_record_request "$(printf '%s' "$req" | head -n 1 | cut -c1-40)" rejected "not a version (X.Y.Z or X.Y.Z-<pre>)"
    return 0
  fi
  if _schemaf_install_running; then
    _schemaf_record_request "$req" rejected "an install is running; request again when it has finished"
    return 0
  fi
  if ! _schemaf_on_channel "$req"; then
    _schemaf_record_request "$req" rejected "a prerelease, and this host's channel is stable"
    return 0
  fi
  if ! running=$(_schemaf_running_version 2>/dev/null); then
    _schemaf_record_request "$req" rejected "the running tag is not a release version"
    return 0
  fi
  if [ -n "$running" ] && ! _schemaf_newer "$req" "$running"; then
    _schemaf_record_request "$req" rejected "not newer than the running $running"
    return 0
  fi
  if [ ! -f "$RELEASES_DIR/$req/${PROJECT_NAME}-${req}.run" ] || [ ! -f "$RELEASES_DIR/$req/${PROJECT_NAME}-${req}.run.sigstore.json" ]; then
    _schemaf_record_request "$req" rejected "not downloaded and verified on this host"
    return 0
  fi
  _schemaf_record_request "$req" accepted "installing $req"
  # Its own process: install's lock and clean-up belong to it. Its outcome is
  # in status.json either way.
  bash "$0" install "$req" || true
  # A request that arrived meanwhile is rejected, not queued.
  req=$(_schemaf_take_request)
  if [ -n "$req" ]; then
    _schemaf_record_request "$(printf '%s' "$req" | head -n 1 | cut -c1-40)" rejected "arrived while an install was running; request again"
  fi
  return 0
}

_schemaf_updater_enable() {
  local dir prefix script="$USER_DIR/bin/schemaf.sh" user linger
  _schemaf_pull_linux_only
  _schemaf_pull_config
  user=$(id -un)
  command -v systemctl >/dev/null 2>&1 || _die "the updater needs systemd (systemctl), and this host has none — run releases and install from cron instead"
  systemctl --user show-environment >/dev/null 2>&1 || _die "systemctl --user does not answer for $user — the updater needs the user's systemd instance (is XDG_RUNTIME_DIR set? log in as $user, or enable lingering: loginctl enable-linger $user)"
  linger=$(loginctl show-user "$user" --property=Linger --value 2>/dev/null || true)
  [ "$linger" = yes ] || _die "lingering is off for $user, so the updater would stop when $user logs out — as root: loginctl enable-linger $user"
  [ -x "$script" ] || _die "$script is missing — the units call it (install a release first, or copy the repository's schemaf.sh there)"
  # The units run in the user's systemd manager, which keeps the groups and
  # environment it started with: the runtime must answer there, not only here.
  if ! systemd-run --user --wait --quiet --collect --setenv=SCHEMAF_RUNTIME="${SCHEMAF_RUNTIME:-podman}" \
      "${SCHEMAF_RUNTIME:-podman}" info >/dev/null 2>&1; then
    _die "${SCHEMAF_RUNTIME:-podman} doesn't answer inside $user's systemd, where the updater's units run$([ "${SCHEMAF_RUNTIME:-podman}" = docker ] && echo " — if $user joined the docker group after its systemd started, restart it (as root): systemctl restart user@$(id -u).service") (try: systemd-run --user --wait ${SCHEMAF_RUNTIME:-podman} info)"
  fi
  dir=$(_schemaf_unit_dir) prefix=$(_schemaf_unit_prefix)
  mkdir -p "$dir"
  _schemaf_updates_files || _die "could not create $UPDATES_DIR"
  cat > "$dir/$prefix-releases.service" <<EOF
# Written by schemaf.sh updater enable (INSTALL.md › The updater).
[Unit]
Description=schemaf: fetch and verify ${PROJECT_NAME}'s releases

[Service]
Type=oneshot
ExecStart=$script releases
EOF
  cat > "$dir/$prefix-releases.timer" <<EOF
# Written by schemaf.sh updater enable (INSTALL.md › The updater).
[Unit]
Description=schemaf: fetch and verify ${PROJECT_NAME}'s releases, hourly

[Timer]
OnBootSec=5min
OnUnitActiveSec=1h

[Install]
WantedBy=timers.target
EOF
  cat > "$dir/$prefix-request.service" <<EOF
# Written by schemaf.sh updater enable (INSTALL.md › The updater).
[Unit]
Description=schemaf: handle ${PROJECT_NAME}'s update request
# No start limit: a burst of requests must never stop the path unit for good.
StartLimitIntervalSec=0

[Service]
Type=oneshot
ExecStart=$script updater request
EOF
  cat > "$dir/$prefix-request.path" <<EOF
# Written by schemaf.sh updater enable (INSTALL.md › The updater).
[Unit]
Description=schemaf: watch ${PROJECT_NAME}'s update request

[Path]
PathModified=$UPDATES_DIR/request

[Install]
WantedBy=default.target
EOF
  systemctl --user daemon-reload
  systemctl --user enable --now "$prefix-releases.timer" "$prefix-request.path" >/dev/null 2>&1 \
    || _die "systemctl --user enable --now $prefix-releases.timer $prefix-request.path failed — see: systemctl --user status $prefix-releases.timer $prefix-request.path"
  echo "enabled $(_schemaf_now)" > "$UPDATES_DIR/updater"
  chmod 644 "$UPDATES_DIR/updater"
  systemctl --user start --no-block "$prefix-releases.service"
  echo "Updater enabled: $prefix-releases.timer (hourly releases), $prefix-request.path (the app's requests). Units in $dir" >&2
}

_schemaf_updater_disable() {
  local dir prefix u
  _schemaf_pull_linux_only
  dir=$(_schemaf_unit_dir) prefix=$(_schemaf_unit_prefix)
  rm -f "$UPDATES_DIR/updater"
  if command -v systemctl >/dev/null 2>&1; then
    systemctl --user disable --now "$prefix-releases.timer" "$prefix-request.path" >/dev/null 2>&1 || true
    systemctl --user stop "$prefix-releases.service" "$prefix-request.service" >/dev/null 2>&1 || true
  fi
  for u in releases.service releases.timer request.service request.path; do
    rm -f "${dir:?}/$prefix-$u"
  done
  if command -v systemctl >/dev/null 2>&1; then systemctl --user daemon-reload || true; fi
  echo "Updater disabled; the app's update API answers \"updater not enabled\"" >&2
}

_schemaf_updater_status() {
  local prefix
  _schemaf_pull_linux_only
  prefix=$(_schemaf_unit_prefix)
  if [ -f "$UPDATES_DIR/updater" ]; then echo "updater: $(cat "$UPDATES_DIR/updater")"; else echo "updater: not enabled"; fi
  if command -v systemctl >/dev/null 2>&1; then
    systemctl --user status "$prefix-releases.timer" "$prefix-request.path" --no-pager 2>&1 || true
    if systemctl --user is-failed --quiet "$prefix-request.path" 2>/dev/null; then
      echo "ERROR: $prefix-request.path has failed: the app's requests are not handled — run: schemaf.sh updater enable" >&2
      return 1
    fi
  fi
}

_schemaf_updater() {
  case "${1:-}" in
    enable) _schemaf_updater_enable ;;
    disable) _schemaf_updater_disable ;;
    status) _schemaf_updater_status ;;
    request) _schemaf_updater_request ;; # run by the path unit
    *) _die "usage: schemaf.sh updater enable | disable | status" ;;
  esac
}

# --- dispatch -----------------------------------------------------------------

CMD="${1:-}"
shift 2>/dev/null || true

# An artifact's header runs the archive's own schemaf.sh: __load <extracted dir>.
if [ "$CMD" = __load ]; then
  echo "schemaf ${SCHEMAF_VER} — ${PROJECT_NAME}" >&2
  [ $# -eq 1 ] && [ -d "$1" ] || _die "__load is called by a deployment artifact: ./${PROJECT_NAME}-<tag>.run load"
  _schemaf_load "$1"
  exit 0
fi

if [ ! -f "$SCRIPT_DIR/schemaf.toml" ]; then
  if [ -d "$USER_DIR/bin" ] && [ "$SCRIPT_DIR" = "$(cd "$USER_DIR/bin" && pwd)" ]; then
    echo "schemaf ${SCHEMAF_VER} — ${PROJECT_NAME} (run side)" >&2
    _schemaf_runside "$CMD" "$@"
    exit 0
  fi
  echo "ERROR: schemaf.toml not found in the same directory as this script."
  echo "       Place schemaf.sh next to your schemaf.toml — see schemaf documentation."
  echo "       (On a run host, use ~/.${PROJECT_NAME}/bin/schemaf.sh, installed by an artifact's load.)"
  exit 1
fi

PROJECT_ROOT="$SCRIPT_DIR"
cd "$PROJECT_ROOT"

# Banner to stderr, so command stdout stays clean for capture (e.g. auth token).
echo "schemaf ${SCHEMAF_VER} — ${PROJECT_NAME}" >&2

# Env files: build reads only SCHEMAF_RUNTIME (see _schemaf_env_runtime), run
# loads the production env after building, everything else the dev env.
# Development mode goes with the dev env file (EXTEND.md › Development mode):
# SCHEMAF_DEV=1 for every command that loads it, never for build or run, whatever
# the caller's shell exports. Env files may not set it (_schemaf_refuse_dev_mode_in).
case "$CMD" in
  build|run) _schemaf_refuse_instance "$CMD" "$@"; unset SCHEMAF_DEV ;;
  *)
    _schemaf_load_env "$USER_DIR/dev/etc/env"
    export SCHEMAF_DEV=1
    ;;
esac

case "$CMD" in
  codegen)
    exec go run github.com/flocko-motion/schemaf/cmd/schemaf codegen
    ;;
  test)
    _schemaf_check_fresh
    go run github.com/flocko-motion/schemaf/cmd/schemaf prerun test "$PROJECT_NAME"

    # No project services: no compose stack. Each test that boots the app
    # gets its own database from the test harness (schemaftest).
    exec go run github.com/flocko-motion/schemaf/cmd/schemaf test "$@"
    ;;
  build)
    _schemaf_env_runtime "$USER_DIR/dev/etc/env"
    _schemaf_build "$@"
    ;;
  run)
    case "${1:-}" in
      --image|--image=*) _die "run --image starts a loaded artifact; on this host use ~/.${PROJECT_NAME}/bin/schemaf.sh run --image <tag> (plain ./schemaf.sh run builds this checkout)" ;;
    esac
    # run = build, then start that image (INSTALL.md › Deployment › Single-user hosts).
    _schemaf_env_runtime "$USER_DIR/etc/env"
    _schemaf_check_runtime compose
    _schemaf_check_volume
    _schemaf_build
    _schemaf_load_env "$USER_DIR/etc/env"
    export SCHEMAF_IMAGE="$BUILT_IMAGE"
    # Dev and production can't coexist: stop the dev stack first.
    if [ -f compose.dev.gen.yml ] \
      && [ -n "$(_schemaf_container compose -f compose.gen.yml -f compose.dev.gen.yml ps -q 2>/dev/null)" ]; then
      echo "Stopping dev services before production start..." >&2
      _schemaf_container compose -f compose.gen.yml -f compose.dev.gen.yml down
    fi
    _schemaf_updates_files || _die "could not create $UPDATES_DIR (the backend mounts it)"
    _schemaf_container --exec compose -f compose.gen.yml up "$@"
    ;;
  dev)
    exec go run "${PROJECT_ROOT}/go" dev "$@"
    ;;
  upgrade)
    TARGET="${1:-}"
    if [ -z "$TARGET" ]; then
      # Query GitHub for the latest tag instead of Go proxy (which caches @latest for ~30min).
      # Capture the full tag list first, then pick the highest version with pure bash.
      # Piping `git ls-remote` into `head` makes git exit on SIGPIPE (141) once head
      # closes the pipe after the first line, which trips `set -o pipefail` + `set -e`.
      TAGS=$(git ls-remote --tags --sort=-v:refname https://github.com/flocko-motion/schemaf.git 'v*' 2>/dev/null || true)
      TARGET=${TAGS%%$'\n'*}   # first line = highest version
      TARGET=${TARGET##*/}     # strip the refs/tags/ prefix
      TARGET=${TARGET%%^*}     # strip any ^{} annotated-tag deref suffix
      if [ -z "$TARGET" ]; then
        echo "ERROR: could not determine latest version from GitHub" >&2
        exit 1
      fi
    fi
    # Accept a bare version ("1.9.0") as well as "v1.9.0" — Go needs the v prefix.
    case "$TARGET" in [0-9]*) TARGET="v$TARGET" ;; esac
    echo "Upgrading schemaf framework to ${TARGET}..."
    cd go
    OLD_VER=$(go list -m -f '{{.Version}}' github.com/flocko-motion/schemaf 2>/dev/null || echo "unknown")
    go get "github.com/flocko-motion/schemaf@${TARGET}"
    NEW_VER=$(go list -m -f '{{.Version}}' github.com/flocko-motion/schemaf)
    cd ..
    if [ "$OLD_VER" = "$NEW_VER" ]; then
      echo "Already at ${NEW_VER}"
    else
      echo "Upgraded: $OLD_VER → $NEW_VER"
    fi
    # Sync framework docs from the installed module into docs/schemaf/.
    SCHEMAF_DIR=$(cd go && go list -m -f '{{.Dir}}' github.com/flocko-motion/schemaf 2>/dev/null || true)
    if [ -n "$SCHEMAF_DIR" ] && [ -d "$SCHEMAF_DIR" ]; then
      mkdir -p docs/schemaf
      rm -f docs/schemaf/CLAUDE.md
      for f in README.md INSTALL.md EXTEND.md; do
        [ -f "$SCHEMAF_DIR/$f" ] && rm -f "docs/schemaf/$f" && cp "$SCHEMAF_DIR/$f" "docs/schemaf/$f" && chmod 644 "docs/schemaf/$f"
      done
      echo "Synced framework docs → docs/schemaf/"
    fi
    echo "Running codegen..."
    go run github.com/flocko-motion/schemaf/cmd/schemaf codegen
    # go.mod and go.sum complete for what the code imports: build compiles
    # with -mod=readonly from go/ alone (INSTALL.md › Lockfiles). Module mode,
    # so go.work.sum can't stand in for go.sum.
    echo "Tidying the Go module..."
    (cd go && GOWORK=off go mod tidy)
    echo "Commit go/go.mod and go/go.sum with the generated files."
    ;;
  *)
    SCHEMAF_CWD="$ORIG_PWD" exec go run "${PROJECT_ROOT}/go" "$CMD" "$@"
    ;;
esac
